package ama.storage;
import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static ama.storage.Task11B2ExactRetryOracle.*;import static ama.storage.Task11B3LifecycleOracle.*;
/** Exact new O5/O6 deltas only; every old full row remains protected. */
final class Task11B3ContinuationOracle {
 static void complete(Map<String,List<Map<String,Object>>> before,Map<String,List<Map<String,Object>>> after,Map<String,List<String>> keys,String meeting,String publication,String operation,String owner,List<String> tasks,List<String> executions,List<Sealed> sealed)throws Exception {
  assertEquals(2,tasks.size());assertEquals(2,executions.size());assertEquals(1,sealed.size());for(int n=0;n<1;n++){assertEquals(tasks.get(n),sealed.get(n).task());assertEquals(executions.get(n),sealed.get(n).execution());requireSealed(sealed.get(n),after,keys);}preserved(before,after,keys,meeting,publication,operation,Set.copyOf(tasks),Set.copyOf(executions));var counts=Map.of("durable_task",2,"external_execution",2,"publication_submission",2,"task_attempt",2,"publication_attempt",1,"idempotency_record",3,"audit_event",3,"task_outbox",9);for(String table:before.keySet())assertEquals(before.get(table).size()+counts.getOrDefault(table,0),after.get(table).size(),table+" exact cumulative count");
  var root=Task11B3LocalOracle.row(after,"meeting","id",meeting);assertEquals("PUBLISH_FAILED",root.get("stage"));assertEquals(java.math.BigInteger.valueOf(13),integer(root.get("revision")));var pub=Task11B3LocalOracle.row(after,"publication","id",publication);assertEquals("RUNNING",pub.get("state"));assertEquals(java.math.BigInteger.valueOf(19),integer(pub.get("revision")));var op=Task11B3LocalOracle.row(after,"external_operation","id",operation);assertEquals("UNKNOWN",op.get("state"));assertEquals(integer(Task11B3LocalOracle.row(before,"external_operation","id",operation).get("current_execution_no")).add(java.math.BigInteger.valueOf(2)),integer(op.get("current_execution_no")));assertEquals(integer(Task11B3LocalOracle.row(before,"external_operation","id",operation).get("reconcile_epoch")).add(java.math.BigInteger.valueOf(5)),integer(op.get("reconcile_epoch")));
  int[] attempts={1,1};String[] reasons={"EXPIRED_UNMARKED_ABANDONED"};
  for(int n=0;n<2;n++){String task=tasks.get(n),execution=executions.get(n);var t=Task11B3LocalOracle.row(after,"durable_task","id",task);assertEquals(n==1?"RECONCILING":"FAILED",t.get("state"));assertEquals(java.math.BigInteger.valueOf(attempts[n]),integer(t.get("attempt")));var e=Task11B3LocalOracle.row(after,"external_execution","id",execution);assertEquals(task,e.get("task_id"));assertEquals(operation,e.get("operation_id"));assertEquals(n==1?"UNKNOWN":"FAILED",e.get("state"));assertEquals(java.math.BigInteger.valueOf(n+7),integer(e.get("execution_no")));var s=Task11B3LocalOracle.row(after,"publication_submission","task_id",task);assertEquals(publication,s.get("publication_id"));assertEquals(java.math.BigInteger.valueOf(n+8),integer(s.get("submission_no")));assertEquals(n==1?"UNDECIDED":"NEVER_MARKED",s.get("local_state"));assertEquals(owner,s.get("requester_id"));assertEquals(e.get("request_manifest"),s.get("request_manifest"));assertEquals(e.get("request_hash"),s.get("execution_request_hash"));
   var a=after.get("task_attempt").stream().filter(row->task.equals(row.get("task_id"))).sorted(Comparator.comparing(row->integer(row.get("attempt")))).toList();assertEquals(attempts[n],a.size());for(int index=0;index<a.size();index++){var row=a.get(index);assertEquals(java.math.BigInteger.valueOf(index+1),integer(row.get("attempt")));if(n==1)assertNull(row.get("ended_at"));else assertNotNull(row.get("ended_at"));}
   if(n<1){assertEquals(reasons[n],s.get("local_reason"));assertEquals(owner,s.get("local_decided_by"));assertEquals(execution,s.get("local_execution_id"));assertEquals(java.math.BigInteger.valueOf(attempts[n]),integer(s.get("local_attempt_no")));assertNull(e.get("marked_at"));assertNull(e.get("task_attempt"));assertEquals("NOT_SENT",e.get("no_effect_basis"));}else{assertNotNull(e.get("marked_at"));assertEquals(java.math.BigInteger.ONE,integer(e.get("task_attempt")));assertNull(e.get("no_effect_basis"));assertNull(s.get("local_decided_at"));}
  }
  var publicationAttempt=added(before,after,keys,"publication_attempt").getFirst();assertEquals(executions.getLast(),publicationAttempt.get("execution_id"));assertEquals(operation,publicationAttempt.get("operation_id"));assertEquals("PENDING",publicationAttempt.get("outcome"));assertEquals("PUBLISH",publicationAttempt.get("kind"));
  var audits=new HashMap<String,Integer>();for(var row:added(before,after,keys,"audit_event")){assertEquals(owner,row.get("actor_id"));assertEquals(meeting,row.get("resource_id"));assertEquals("SUCCEEDED",row.get("result"));assertEquals(java.math.BigInteger.valueOf(13),integer(row.get("revision")));audits.merge((String)row.get("action"),1,Integer::sum);}assertEquals(Map.of("PUBLICATION_RESUBMITTED",2,"PUBLICATION_LOCAL_NEVER_MARKED",1),audits);
  var eventCounts=new HashMap<String,Integer>();var sequences=new TreeSet<java.math.BigInteger>();for(var event:added(before,after,keys,"task_outbox")){eventCounts.merge((String)event.get("event_type"),1,Integer::sum);assertTrue(sequences.add(integer(event.get("sequence_id"))));}assertEquals(Map.of("TASK_ENQUEUED",2,"PUBLICATION_ACCEPTED",2,"TASK_FAILED",1,"PUBLICATION_LOCAL_RECOVERED",1,"TASK_RECONCILING",1,"EXTERNAL_MARKED",1,"EXTERNAL_UNKNOWN",1),eventCounts);var first=integer(before.get("task_outbox_sequence").getFirst().get("next_id"));for(int i=0;i<9;i++)assertTrue(sequences.contains(first.add(java.math.BigInteger.valueOf(i))));assertEquals(first.add(java.math.BigInteger.valueOf(9)),integer(after.get("task_outbox_sequence").getFirst().get("next_id")));
  var receipts=added(before,after,keys,"idempotency_record");for(int n=1;n<=2;n++){String task=tasks.get(n-1),key="task11-b3-continuation-resubmit-"+n;var found=receipts.stream().filter(row->task.equals(row.get("result_id"))&&"PUBLICATION_RESUBMIT".equals(row.get("operation"))).toList();assertEquals(1,found.size());receipt(found.getFirst(),owner,meeting,task,key,202);var sub=Task11B3LocalOracle.row(after,"publication_submission","task_id",task);assertEquals(Task11B3LocalOracle.digest(publication,"13",Integer.toString(13+2*n),(String)sub.get("confirmation_id"),(String)sub.get("provider_id"),(String)sub.get("library_id"),(String)sub.get("folder_id")),found.getFirst().get("request_hash"));}
  for(int n:List.of(1)){String task=tasks.get(n-1),key="task11-b3-continuation-local-"+n;var found=receipts.stream().filter(row->task.equals(row.get("result_id"))&&"PUBLICATION_LOCAL_RECOVERY".equals(row.get("operation"))).toList();assertEquals(1,found.size());receipt(found.getFirst(),owner,meeting,task,key,200);assertEquals(Task11B3LocalOracle.digest(publication,task,"13",Integer.toString(14+2*n)),found.getFirst().get("request_hash"));}
 }
}
